const SAFE_FILENAME = /^[\w.-]+$/

/** Plain archives end in `.tar.gz`; encrypted ones in `.tar.gz.enc`. */
export const ARCHIVE_EXTENSION = '.tar.gz'
export const ENCRYPTED_EXTENSION = '.tar.gz.enc'

/** Archive names are generated by the plugin; reject anything that could escape a folder. */
export const assertSafeFilename = (filename: string): string => {
  if (!SAFE_FILENAME.test(filename) || filename.startsWith('.')) {
    throw new Error(`Invalid backup filename: "${filename}"`)
  }
  return filename
}

/** Whether a file in storage looks like one of the plugin's archives. */
export const isArchiveFilename = (filename: string): boolean =>
  filename.endsWith(ARCHIVE_EXTENSION) || filename.endsWith(ENCRYPTED_EXTENSION)

export const createBackupFilename = (date = new Date(), { encrypted = false } = {}): string => {
  const stamp = date.toISOString().replace(/[:.]/g, '-')
  const random = Math.random().toString(36).slice(2, 8)
  return `backup-${stamp}-${random}${encrypted ? ENCRYPTED_EXTENSION : ARCHIVE_EXTENSION}`
}
